    E("2020-03", "ind:semi", "+", "비대면 수요로 서버·PC 호조", "재택근무·온라인 수업으로 서버와 노트북 수요가 늘어 메모리 업황이 빠르게 회복됐고, 2021년 초 '슈퍼사이클 재림' 기대가 정점에 달했어요.", end="2021-01"),
    E("2021-08", "ind:semi", "-", "'메모리 겨울이 온다' 보고서", "8월 모건스탠리가 메모리 가격 하락을 경고하는 보고서를 내며 반도체주가 급락했어요. 실제 업황 하락은 2022년 하반기에 본격화돼, 주가가 실적보다 1년가량 먼저 움직였어요.", end="2021-10"),
    E("2022-07", "ind:semi", "-", "재고 급증·메모리 가격 급락", "PC·스마트폰 수요 급감으로 고객사 재고가 쌓여 D램·낸드 가격이 큰 폭으로 떨어졌어요. 삼성전자 반도체는 2023년 1분기 약 4.6조원 적자를 냈어요.", end="2023-03"),
    E("2023-04", "ind:semi", "+", "삼성전자 감산 공식화 → 바닥 신호", "4월 7일 삼성전자가 메모리 감산을 공식화하자 공급 과잉 해소 기대로 업황 바닥론이 확산됐어요. 실적은 최악인데 주가가 먼저 오른 구간이에요."),
    E("2023-05", "ind:semi", "+", "AI 붐·HBM 수요 폭발", "5월 24일 엔비디아의 매출 전망 대폭 상향 이후 AI 서버용 고대역폭메모리(HBM) 수요가 급증했어요. HBM을 주도한 SK하이닉스와 TC본더 등 HBM 후공정 장비·부품사가 급등했어요.", end="2024-06"),
    E("2024-07", "ind:semi", "-", "AI 반도체 피크아웃 우려", "7월 빅테크 AI 투자 회의론, 8월 5일 블랙먼데이, 9월 모건스탠리의 메모리 '겨울이 곧 온다' 보고서가 이어지며 반도체주가 급락했어요. 범용 D램 수요 부진과 중국 업체 증설이 우려 요인이었어요.", end="2024-11"),
    E("2025-01", "ind:semi", "-", "딥시크 쇼크", "1월 말 중국 딥시크가 저비용 AI 모델을 공개해 AI 투자 축소 우려로 HBM·AI 장비주가 하루 크게 빠졌어요."),
    E("2025-06", "ind:semi", "+", "메모리 가격 반등·AI 슈퍼사이클", "AI 서버 수요가 범용 D램·낸드로 번지고 공급이 HBM으로 쏠리면서 하반기 메모리 가격이 급등했어요. 10월 1일 오픈AI '스타게이트'에 삼성·SK가 월 최대 90만장 웨이퍼 공급 협력 의향서를 맺으며 기대가 커졌어요.", end="2025-12"),

