    E("2020-07", "ind:battery", "+", "전기차 기대 랠리", "테슬라 급등과 유럽 탄소규제 강화로 전기차 성장 기대가 커져, 실적보다 몇 년 뒤 생산능력(CAPA) 기대가 주가에 반영됐어요.", end="2021-08"),
    E("2022-08", "ind:battery", "+", "미국 IRA 서명", "8월 16일 인플레이션감축법으로 미국에서 만든 셀(kWh당 35달러)·모듈(10달러)에 생산세액공제가 생겨 미국 공장을 가진 한국 셀·소재사가 수혜를 받았어요."),
    E("2022-11", "ind:battery", "-", "리튬 가격 정점 → 급락", "탄산리튬이 11월 톤당 약 60만위안으로 사상 최고를 찍은 뒤 1년 만에 약 80% 떨어졌어요. 판가가 메탈 가격에 연동되는 양극재·리튬 회사는 매출과 재고평가에서 손실을 봤어요.", end="2023-12", groups=["양극재·전구체", "리튬·원료·재활용", "셀"]),
    E("2023-01", "ind:battery", "+", "2차전지 광풍", "개인 투자자 매수가 몰리며 에코프로가 연초 대비 10배 넘게 오르는 등 소재주가 급등했어요. 7월 26일 정점에서 하루 급락한 뒤 긴 조정이 시작됐어요. 실적보다 배수(PER)가 수백 배까지 오른 구간이에요.", end="2023-07"),
    E("2023-08", "ind:battery", "-", "전기차 수요 둔화(캐즘)", "고금리와 보조금 축소로 전기차 판매 증가율이 꺾여 셀 가동률과 소재 판가가 함께 떨어졌어요. 2024년 대부분의 소재사 이익이 급감하거나 적자로 돌았어요.", end="2024-12"),
    E("2024-08", "ind:battery", "-", "인천 전기차 화재", "8월 1일 인천 청라 아파트 지하주차장 전기차 화재로 배터리 안전 우려가 커져 국내 전기차 수요가 위축됐어요."),
    E("2024-11", "ind:battery", "-", "트럼프 당선·IRA 축소 우려", "전기차 세액공제 폐지 가능성이 부각되며 미국 매출 비중이 큰 셀·소재사 주가가 빠졌어요."),
    E("2025-07", "ind:battery", "±", "미국 감세법(OBBBA) 서명", "7월 4일 서명된 법으로 미국 전기차 소비자 세액공제가 9월 30일 종료됐어요. 생산세액공제는 남았지만 중국산 소재 사용 제한이 강화됐고, 업계는 ESS(에너지저장장치)로 무게중심을 옮겼어요."),
    E("2025-06", "ind:battery", "+", "ESS 수요 급증", "AI 데이터센터 전력 수요로 미국 ESS 주문이 늘며 LFP 배터리 현지 생산 기대가 커졌어요.", end="2025-12", groups=["셀", "양극재·전구체", "장비", "부품·케이스"]),

